mapper.select:
SELECT iti.REL_ID as relId, iti.REL_NAME as relName, iti.TRAN_TYPE as tranType, iti.REMARK as remark, iti.TRAN_DATE as tranDate, iti.TRA_SUB_NAME as traSubName, iti.manager_org as managerOrg, SUM(iti.prac_trade_amount) over(partition by rel_id,tran_type,investment_type
,manager_org
) as contractAmount, iti.investment_type AS tranOverView FROM ins_tra_investment iti WHERE iti.STATUS IN ('6','7','10') AND iti.DELFLAG_ = '1' and iti.tran_type is not null and iti.prac_trade_amount is not null and iti.investment_type is not null
and to_char(iti.TRAN_DATE,'YYYY-MM-DD') BETWEEN #{staTime} AND #{endTime}

FROM ins_tra_investment WHERE consider_type = '2' AND STATUS = '3' AND prac_trade_amount IS NOT NULL AND DELFLAG_ = '1'
AND CREATED_TIME_ like #{param.year}
AND (CREATED_TIME_ like #{param.begin} or CREATED_TIME_ like #{param.center} or CREATED_TIME_ like #{param.end})

SELECT sum(PRAC_TRADE_AMOUNT) as PRAC_TRADE_AMOUNT,count(*) as pid ,'1' as TRAN_TYPE FROM ins_tra_funds WHERE 1=1 and DELFLAG_ = '1' and status = '6'
and TRAN_DATE like #{param.year}
and TRAN_DATE >= #{param.beginQuarter}
and TRAN_DATE <= #{param.endQuarter}
and TRAN_DATE >= #{param.startTranDate}
and TRAN_DATE <= #{param.endTranDate}
union all SELECT sum(PRAC_TRADE_AMOUNT) as PRAC_TRADE_AMOUNT,count(*) as pid, '4' as TRAN_TYPE FROM ins_tra_business WHERE 1=1 and DELFLAG_ = '1' and status = '6'
and contract_Date like #{param.year}
and contract_Date >= #{param.beginQuarter}
and contract_Date <= #{param.endQuarter}
and contract_Date >= #{param.startTranDate}
and contract_Date <= #{param.endTranDate}
union all SELECT sum(PRAC_TRADE_AMOUNT) as PRAC_TRADE_AMOUNT,count(*) as pid,'3' as TRAN_TYPE FROM ins_tra_interest WHERE 1=1 and DELFLAG_ = '1' and status = '6'
and contract_Date like #{param.year}
and contract_Date >= #{param.beginQuarter}
and contract_Date <= #{param.endQuarter}
and contract_Date >= #{param.startTranDate}
and contract_Date <= #{param.endTranDate}
union all SELECT sum(PRAC_TRADE_AMOUNT) as PRAC_TRADE_AMOUNT,count(*) as pid,'2' as TRAN_TYPE FROM ins_tra_service WHERE 1=1 and DELFLAG_ = '1' and status = '6'
and contract_Date like #{param.year}
and contract_Date >= #{param.beginQuarter}
and contract_Date <= #{param.endQuarter}
and contract_Date >= #{param.startTranDate}
and contract_Date <= #{param.endTranDate}
